internal static class CaptureOwnerTests {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static async Task Until(Func<bool> predicate){var deadline=DateTimeOffset.UtcNow.AddSeconds(5);while(!predicate()&&DateTimeOffset.UtcNow<deadline)await Task.Delay(5);Check(predicate(),"Modeled owner did not reach expected state");}
    sealed class ModeledInvocation:ICaptureInvocation {
        public string InvocationId{get;}=Guid.NewGuid().ToString("N");public string Generation{get;}=Guid.NewGuid().ToString("N");
        public bool Started{get;private set;}public bool RetirementProven{get;set;}public bool FailNative;public TaskCompletionSource Release=new(TaskCreationOptions.RunContinuationsAsynchronously);public bool Stopping;
        public CaptureProducerFacts Facts()=>new(Started,Started,Started,Started?3:0,Started?2:0,Started?"10":null,Started?"20":null,Started?DateTimeOffset.UtcNow.AddMilliseconds(-1):null,Started?DateTimeOffset.UtcNow:null);
        public CaptureTerminalFacts? Terminal=>RetirementProven||FailNative?new(FailNative?1:0,true,true,FailNative?1:0,true,true,true,true,"modeled terminal"):null;
        public async Task Run(CaptureFanout fanout,CancellationToken stop){Started=true;fanout.SetMetadata(new{kind="video"});try{await Task.Delay(Timeout.Infinite,stop);}catch(OperationCanceledException){}Stopping=true;await Release.Task;if(FailNative)throw new InvalidDataException("Modeled native1");RetirementProven=true;}
    }
    static CaptureOwnerAction Action(CaptureOwnerConfig config,OwnedSource source,string action="start",CaptureOwnerResult? result=null)=>new("questms.capture.action.v2",Guid.NewGuid().ToString("D"),action,source.SourceId,config.OwnerEpoch,source.OwnerBindingRef.Sha256,result is null?null:new(result.InvocationId,result.Generation));
    static CaptureOwnerResult Result(CaptureOwnerService service,string id)=>(CaptureOwnerResult)service.Original(id).Body;
    static string NewRoot(){var root=Path.Combine(Path.GetTempPath(),"qms-capture-owner-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);return root;}
    static CaptureOwnerConfig Config(string root)=>new("questms.capture.owner.v1","modeled-"+Guid.NewGuid().ToString("N"),Convert.ToHexString(RandomNumberGenerator.GetBytes(32)),root);
    static readonly OwnedSource Q=new("Q","deviceQ","Q",new("fixture",1,new string('a',64))),W=new("W","deviceW","W",new("fixture",1,new string('b',64)));
    public static async Task Run(){await CaptureOwnerModeTests.Run();await Originals();await PreDispatchStop();await AppStopAdmission();await OriginalStops();await Unknown();Recovery();Authentication();Console.WriteLine("PASS actual capture service/transport: durable original joins, two server-owned feeds/no page, independent stop/rearm, stale Stop refusal, lost reply dedup, pre-dispatch Stop, delayed Start after app Stop denied/no-dispatch, cancel-original before arrival/queued/running/rearm/recovery, native1 unknown/restart block, hostile MAC/peer/Host/Origin, timestamp replay window/clock/restart; modeled effects only, no listeners/devices");}
    public static async Task Export(string output){
        if(!Path.IsPathFullyQualified(output)||File.Exists(output))throw new InvalidDataException("Create-new fixture output required");
        var root=NewRoot();try{var config=Config(root) with{Key=new string('t',43),OwnerEpoch="MODELED-interop-only"};var producer=new ModeledInvocation();var allocations=0;using var service=new CaptureOwnerService(config,[Q],_=>allocations++==0?producer:new ModeledInvocation(),_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);
            var now=DateTimeOffset.Parse("2026-10-16T12:00:00Z",System.Globalization.CultureInfo.InvariantCulture);var wire=new CaptureOwnerTransport(config,service,"127.0.0.1:41234",()=>now);var action=Action(config,Q);service.Submit(action);await Until(()=>producer.Started);var fixtures=new List<object>();
            foreach(var path in new[]{"/api/owner/capture-actions/"+action.RequestId,"/api/owner/captures/Q","/api/owner/status"}){
                var nonce=CaptureOwnerTransport.NewNonce(now);var requestMac=HubOwnerBridge.Mac(config.Key,CaptureOwnerTransport.RequestDomain,"GET",path,config.OwnerEpoch,nonce,[]);var headers=new List<KeyValuePair<string,string>>{new("Host","127.0.0.1:41234"),new("X-Quest-Owner-Epoch",config.OwnerEpoch),new("X-Quest-Nonce",nonce),new("X-Quest-Mac",requestMac)};var response=wire.Exchange("GET",path,headers,[],IPAddress.Loopback);
                fixtures.Add(new{method="GET",path,nonce,requestMac,status=response.Status,headers=response.Headers,bodyBase64=Convert.ToBase64String(response.Body),requestBodyBase64=""});
            }
            var delayed=Action(config,Q);var cancel=Cancel(config,delayed);
            foreach(var (method,path,body) in new[]{("POST","/api/owner/capture-actions",JsonSerializer.SerializeToUtf8Bytes(cancel,OwnerJson.Options)),("GET","/api/owner/capture-actions/"+cancel.RequestId,Array.Empty<byte>()),("POST","/api/owner/capture-actions",JsonSerializer.SerializeToUtf8Bytes(delayed,OwnerJson.Options)),("GET","/api/owner/capture-actions/"+delayed.RequestId,Array.Empty<byte>())}){
                var nonce=CaptureOwnerTransport.NewNonce(now);var requestMac=HubOwnerBridge.Mac(config.Key,CaptureOwnerTransport.RequestDomain,method,path,config.OwnerEpoch,nonce,body);var headers=new List<KeyValuePair<string,string>>{new("Host","127.0.0.1:41234"),new("X-Quest-Owner-Epoch",config.OwnerEpoch),new("X-Quest-Nonce",nonce),new("X-Quest-Mac",requestMac)};if(method=="POST")headers.Add(new("Content-Type","application/json"));var response=wire.Exchange(method,path,headers,body,IPAddress.Loopback);Check(response.Status is 200 or 202,"Actual cancel-original wire fixture refused");fixtures.Add(new{method,path,nonce,requestMac,status=response.Status,headers=response.Headers,bodyBase64=Convert.ToBase64String(response.Body),requestBodyBase64=Convert.ToBase64String(body)});
            }
            CaptureOwnerService.Create(output,JsonSerializer.SerializeToUtf8Bytes(new{schema="MODELED.capture-production-wire-fixtures.v1",key=config.Key,epoch=config.OwnerEpoch,clockUnixMs=now.ToUnixTimeMilliseconds(),sources=service.Status().Sources,action,cancel,delayed,fixtures,listener=false,deviceEffects=false},OwnerJson.Options));
            var stop=Action(config,Q,"stop",Result(service,action.RequestId));service.Submit(stop);producer.Release.SetResult();await Until(()=>Result(service,stop.RequestId).State=="retired");
        }finally{Directory.Delete(root,true);}
    }
    public static async Task RealProcesses(OwnedDisplaySelection selected){
        var root=Path.Combine(selected.OutputDirectory,"manager-journal");Directory.CreateDirectory(root);var config=Config(root);
        using var service=new CaptureOwnerService(config,selected.Sources,s=>new SelectedCaptureInvocation(selected,s),_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);
        var q=selected.Sources.Single(s=>s.SourceId=="Q");var w=selected.Sources.Single(s=>s.SourceId=="W");var qa=Action(config,q);var wa=Action(config,w);service.Submit(qa);service.Submit(wa);
        await Until(()=>Result(service,qa.RequestId).State=="streaming"&&Result(service,wa.RequestId).State=="streaming");
        var qr=Result(service,qa.RequestId);Check(qr.Producer?.VideoPackets==2&&qr.Producer.PreviousPtsUs=="1"&&qr.Producer.LastPtsUs=="2","Production publication counter/PTS facts differ");
        var originalStop=Cancel(config,qa);service.SubmitOriginalStop(originalStop);await Until(()=>CancelResult(service,originalStop).State=="retired");Check(CancelResult(service,originalStop).Target?.Terminal is {LocalChildExitCode:0,NativeChildExitCode:0,StdoutEof:true,StderrEof:true,RemoteAckMatched:true,ResourcesRetired:true},"Original-target Stop lost actual production terminal/EOF");
        var qs=Action(config,q,"stop",qr);service.Submit(qs);await Until(()=>Result(service,qs.RequestId).State=="retired");Check(Result(service,wa.RequestId).State=="streaming","Production manager Q Stop retired W");
        var ws=Action(config,w,"stop",Result(service,wa.RequestId));service.Submit(ws);await Until(()=>Result(service,ws.RequestId).State=="retired");Check(Result(service,qs.RequestId).Terminal is {LocalChildExitCode:0,NativeChildExitCode:0,StdoutEof:true,StderrEof:true,RemoteAckMatched:true,ResourcesRetired:true},"Production manager terminal join lost");
        Console.WriteLine("PASS actual capture service with production SelectedCaptureInvocation/OwnedDisplayProducer and two modeled Python children: config/key/advancing PTS, original joins, independent Stop/terminal/fullEOF; no listener/device");
    }
    static async Task Originals(){var root=NewRoot();try{
        var config=Config(root);var producers=new Dictionary<string,ModeledInvocation>();var launched=0;
        using var service=new CaptureOwnerService(config,[Q,W],s=>{var value=new ModeledInvocation();producers[s.SourceId]=value;launched++;return value;},_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);
        var qa=Action(config,Q);var wa=Action(config,W);Check(service.Submit(qa).Status==202&&service.Submit(wa).Status==202,"Both no-page intents not accepted");
        await Until(()=>producers.Values.All(p=>p.Started));var old=Result(service,qa.RequestId);Check(old.State=="streaming"&&old.ActualEffectsCompleted&&old.Producer?.LastPtsUs=="20","Actual advancing packet facts lost");
        Check(File.Exists(Path.Combine(root,"operations",qa.RequestId,"INTENT.json"))&&File.Exists(Path.Combine(root,"operations",qa.RequestId,"DISPATCH.json")),"Dispatch lacks durable intent");
        // Discard original POST response, reconcile its exact ID, then duplicate:
        Check(service.Submit(qa).Status==200&&launched==2,"Lost POST replay created producer");
        Check(service.Submit(qa with{Action="stop",ExpectedInvocation=new(old.InvocationId,old.Generation)}).Status==409,"Changed original ID accepted");
        var wrong=Action(config,Q,"stop",old) with{ExpectedInvocation=new(new string('0',32),old.Generation)};Check(service.Submit(wrong).Status==409&&!producers["Q"].Stopping,"Foreign invocation Stop cancelled producer");
        var qs=Action(config,Q,"stop",old);Check(service.Submit(qs).Status==202,"Q Stop denied");await Until(()=>producers["Q"].Stopping);Check(!producers["W"].Stopping,"Q stop touched W");
        var ws=Action(config,W,"stop",Result(service,wa.RequestId));Check(service.Submit(ws).Status==202,"Blocked Q drain prevented W Stop");await Until(()=>producers["W"].Stopping);producers["W"].Release.SetResult();await Until(()=>Result(service,ws.RequestId).State=="retired");
        Check(Result(service,qs.RequestId).State=="stopping","Stop completed before actual retirement");producers["Q"].Release.SetResult();await Until(()=>Result(service,qs.RequestId).State=="retired");
        var fresh=Action(config,Q);service.Submit(fresh);await Until(()=>producers["Q"].Started);Check(Result(service,fresh.RequestId).InvocationId!=old.InvocationId,"Rearm reused producer");
        Check(Result(service,qa.RequestId).InvocationId==old.InvocationId&&Result(service,qs.RequestId).InvocationId==old.InvocationId,"Old original followed mutable source rearm");
        Check(service.Submit(Action(config,Q,"stop",old)).Status==409,"Old Stop cancelled new source");
        var end=Action(config,Q,"stop",Result(service,fresh.RequestId));service.Submit(end);await Until(()=>producers["Q"].Stopping);producers["Q"].Release.SetResult();await Until(()=>Result(service,end.RequestId).State=="retired");
    }finally{Directory.Delete(root,true);}}
    static async Task PreDispatchStop(){var root=NewRoot();try{var config=Config(root);var guard=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var producer=new ModeledInvocation();using var service=new CaptureOwnerService(config,[Q],_=>producer,async _=>{entered.SetResult();await guard.Task;},(_,_)=>{},(_,_,_)=>{},default);
        var action=Action(config,Q);service.Submit(action);await entered.Task;var stop=Action(config,Q,"stop",Result(service,action.RequestId));service.Submit(stop);guard.SetResult();await Until(()=>Result(service,stop.RequestId).State=="retired");Check(!producer.Started&&Result(service,stop.RequestId).NoDispatchProven&&Result(service,stop.RequestId).Terminal is null&&!File.Exists(Path.Combine(root,"operations",action.RequestId,"DISPATCH.json")),"Stop manufactured terminal or allowed queued Start");
    }finally{Directory.Delete(root,true);}}
    static async Task AppStopAdmission(){
        OwnerLiveStatus Status(string phase,bool unresolved=false){var now=DateTimeOffset.UtcNow;return new("questms.owner.status.v1","modeled",1,now,now.AddSeconds(5),new("pair","session",[new("Q","deviceQ"),new("W","deviceW")]),phase,null,unresolved,new(false,false,[]),new("native","53",[new("Q","qp","50"),new("W","wp","48")]),[],[],"modeled current owner");}
        foreach(var phase in new[]{"starting","running"}){var report=Status(phase);report.Validate("modeled",DateTimeOffset.UtcNow);AppCaptureAdmission.Require(report,Q);}
        foreach(var phase in new[]{"stopping","stopped","unknown","reconciling","failed","preparing"}){
            var root=NewRoot();try{var config=Config(root);var gate=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var producer=new ModeledInvocation();
                using var service=new CaptureOwnerService(config,[Q],_=>producer,async source=>{await gate.Task;var report=Status(phase);report.Validate("modeled",DateTimeOffset.UtcNow);AppCaptureAdmission.Require(report,source);},(_,_)=>{},(_,_,_)=>{},default);
                // A delayed HTTP Start reaches admission after the human app Stop.
                var action=Action(config,Q);service.Submit(action);Check(Result(service,action.RequestId).RetirementPending,"Delayed intent not retained");gate.SetResult();await Until(()=>Result(service,action.RequestId).State=="failed");var result=Result(service,action.RequestId);
                Check(!producer.Started&&result.NoDispatchProven&&!result.RetirementPending&&result.Terminal is null&&File.Exists(Path.Combine(root,"operations",action.RequestId,"NO_DISPATCH.json"))&&!File.Exists(Path.Combine(root,"operations",action.RequestId,"DISPATCH.json")),"App Stop allowed late display dispatch or invented native terminal");
            }finally{Directory.Delete(root,true);}
        }
        try{AppCaptureAdmission.Require(Status("running",true),Q);throw new Exception("Unresolved native operation admitted display");}catch(InvalidDataException){}
        try{AppCaptureAdmission.Require(Status("running"),Q with{DeviceId="foreign"});throw new Exception("Foreign device admitted display");}catch(InvalidDataException){}
    }
    static CaptureOriginalStopAction Cancel(CaptureOwnerConfig config,CaptureOwnerAction start)=>new("questms.capture.action.v3",Guid.NewGuid().ToString("D"),"stop",start.SourceId,config.OwnerEpoch,start.SourceBindingSha256,start.RequestId);
    static CaptureOriginalStopResult CancelResult(CaptureOwnerService service,CaptureOriginalStopAction stop)=>(CaptureOriginalStopResult)service.Original(stop.RequestId).Body;
    static async Task OriginalStops(){
        var root=NewRoot();try{var config=Config(root);var late=Action(config,Q);var cancelled=Cancel(config,late);var producers=new List<ModeledInvocation>();var guards=0;
            using(var service=new CaptureOwnerService(config,[Q,W],_=>{var producer=new ModeledInvocation();producers.Add(producer);return producer;},_=>{guards++;return Task.CompletedTask;},(_,_)=>{},(_,_,_)=>{},default)){
                var reply=service.SubmitOriginalStop(cancelled);var proof=(CaptureOriginalStopResult)reply.Body;Check(reply.Status==202&&proof is {State:"retired",ActualEffectsCompleted:true,RetirementPending:false,NoDispatchProven:true,Target:null},"Absent original Stop invented invocation/terminal or lacked cancellation proof");
                Check(File.Exists(proof.Receipt)&&File.Exists(Path.Combine(root,"original-stops",cancelled.RequestId,"INTENT.json")),"Stop acknowledged without durable intent/tombstone");
                Check(service.SubmitOriginalStop(cancelled).Status==200&&service.SubmitOriginalStop(cancelled with{OriginalStartRequestId=Guid.NewGuid().ToString("D")}).Status==409,"Changed cancellation original accepted");
                Check(service.Submit(late with{RequestId=cancelled.RequestId}).Status==409,"Stop ID reused as Start");
                var other=Action(config,Q);service.Submit(other);await Until(()=>Result(service,other.RequestId).State=="streaming");var current=(CaptureCurrent)service.Current("Q").Body;
                Check(service.SubmitOriginalStop(Cancel(config,other) with{SourceId=W.SourceId,SourceBindingSha256=W.OwnerBindingRef.Sha256}).Status==409&&!producers[0].Stopping,"Foreign source cancellation affected current producer");
                var delayed=service.Submit(late);var denied=(CaptureOwnerResult)delayed.Body;Check(denied is {State:"failed",NoDispatchProven:true,RetirementPending:false,Terminal:null}&&guards==1&&!producers[1].Started,"Delayed old POST started after later app lifetime");
                Check(((CaptureCurrent)service.Current("Q").Body).OriginalStartRequestId==other.RequestId&&!producers[0].Stopping,"Old cancelled original replaced current feed");
                service.SubmitOriginalStop(cancelled with{RequestId=Guid.NewGuid().ToString("D")});Check(!producers[0].Stopping&&CancelResult(service,cancelled).NoDispatchProven,"Old Stop cancelled rearmed feed");
                var stop=Cancel(config,other);service.SubmitOriginalStop(stop);await Until(()=>producers[0].Stopping);Check(CancelResult(service,stop).RetirementPending&&!CancelResult(service,stop).ActualEffectsCompleted,"Pending retirement claimed complete");producers[0].Release.SetResult();await Until(()=>CancelResult(service,stop).State=="retired");Check(CancelResult(service,stop).Target?.Terminal?.NativeChildExitCode==0,"Actual target terminal not retained");
            }
            // Recovery validates positive proof and never replays prior operations.
            var runs=0;using(var recovered=new CaptureOwnerService(config,[Q,W],_=>{runs++;return new ModeledInvocation();},_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default)){Check(CancelResult(recovered,cancelled).NoDispatchProven&&recovered.Submit(late).Status==200&&runs==0,"Recovered cancellation replayed Start");}
        }finally{Directory.Delete(root,true);}
        root=NewRoot();try{var config=Config(root);var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var guard=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var producer=new ModeledInvocation();using var service=new CaptureOwnerService(config,[Q],_=>producer,async _=>{entered.SetResult();await guard.Task;},(_,_)=>{},(_,_,_)=>{},default);var start=Action(config,Q);service.Submit(start);await entered.Task;var stop=Cancel(config,start);service.SubmitOriginalStop(stop);Check(CancelResult(service,stop).RetirementPending,"Awaiting guard silently retired");guard.SetResult();await Until(()=>CancelResult(service,stop).State=="retired");Check(!producer.Started&&CancelResult(service,stop).NoDispatchProven,"Original cancellation lost after awaited guard");
        }finally{Directory.Delete(root,true);}
        root=NewRoot();try{var config=Config(root);var producer=new ModeledInvocation{FailNative=true};using var service=new CaptureOwnerService(config,[Q],_=>producer,_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);var start=Action(config,Q);service.Submit(start);await Until(()=>producer.Started);var stop=Cancel(config,start);service.SubmitOriginalStop(stop);producer.Release.SetResult();await Until(()=>CancelResult(service,stop).State=="unknown");Check(CancelResult(service,stop) is {ActualEffectsCompleted:false,RetirementPending:true,NoDispatchProven:false}&&CancelResult(service,stop).Target?.Terminal?.NativeChildExitCode==1,"Original Stop promoted native1");producer.RetirementProven=true; // Fixture teardown only.
        }finally{Directory.Delete(root,true);}
        root=NewRoot();try{var config=Config(root);var start=Action(config,Q);var stop=Cancel(config,start);using(var service=new CaptureOwnerService(config,[Q],_=>new ModeledInvocation(),_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default)){service.SubmitOriginalStop(stop);}
            File.Delete(Path.Combine(root,"cancelled-originals",start.RequestId+".json"));var factories=0;try{using var rejected=new CaptureOwnerService(config,[Q],_=>{factories++;return new ModeledInvocation();},_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);throw new Exception("Incomplete Stop recovery accepted");}catch(InvalidDataException){}Check(factories==0,"Incomplete journal recovery dispatched effect");
        }finally{Directory.Delete(root,true);}
    }
    static async Task Unknown(){var root=NewRoot();try{var config=Config(root);var producer=new ModeledInvocation{FailNative=true};using var service=new CaptureOwnerService(config,[Q],_=>producer,_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);var action=Action(config,Q);service.Submit(action);await Until(()=>producer.Started);File.Delete(Path.Combine(root,"operations",action.RequestId,"DISPATCH.json"));var stop=Action(config,Q,"stop",Result(service,action.RequestId));service.Submit(stop);producer.Release.SetResult();await Until(()=>Result(service,stop.RequestId).State=="unknown");Check(Result(service,stop.RequestId).RetirementPending&&!Result(service,stop.RequestId).NoDispatchProven&&!Result(service,stop.RequestId).ActualEffectsCompleted&&Result(service,stop.RequestId).Terminal?.NativeChildExitCode==1,"Native1 or lost marker became retired/no-dispatch");Check(service.Submit(Action(config,Q)).Status==409,"Unknown producer replaced");producer.RetirementProven=true; // Fixture teardown only, never a production release path.
    }finally{Directory.Delete(root,true);}}
