        CaptureOwnerService.Create(Path.Combine(directory,"INTENT.json"),JsonSerializer.SerializeToUtf8Bytes(action,OwnerJson.Options));CaptureOwnerService.Create(Path.Combine(directory,"INSTANCE.json"),JsonSerializer.SerializeToUtf8Bytes(new CaptureInstanceRecord("questms.capture.instance.v1",config.OwnerEpoch,"Q","deviceQ",Q.OwnerBindingRef.Sha256,action.RequestId,new string('1',32),new string('2',32)),OwnerJson.Options));CaptureOwnerService.Create(Path.Combine(directory,"RESULT.json"),JsonSerializer.SerializeToUtf8Bytes(new CaptureOwnerResult("questms.capture.result.v2",config.OwnerEpoch,action.RequestId,"start","Q","deviceQ",Q.OwnerBindingRef.Sha256,new string('1',32),new string('2',32),"running",false,true,false,null,null,"modeled interrupted process"),OwnerJson.Options));var factories=0;
        using var service=new CaptureOwnerService(config,[Q],_=>{factories++;return new ModeledInvocation();},_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);Check(Result(service,action.RequestId).State=="unknown"&&service.Submit(Action(config,Q)).Status==409&&factories==0,"Restart replayed or cleared unresolved intent");
    }finally{Directory.Delete(root,true);}}
    static void Authentication(){var root=NewRoot();try{var config=Config(root);using var service=new CaptureOwnerService(config,[Q],_=>new ModeledInvocation(),_=>Task.CompletedTask,(_,_)=>{},(_,_,_)=>{},default);var now=DateTimeOffset.UtcNow;var wire=new CaptureOwnerTransport(config,service,"127.0.0.1:41234",()=>now);
        List<KeyValuePair<string,string>> Headers(string nonce,string path="/api/owner/status",string domain=CaptureOwnerTransport.RequestDomain)=>new(){new("Host","127.0.0.1:41234"),new("X-Quest-Owner-Epoch",config.OwnerEpoch),new("X-Quest-Nonce",nonce),new("X-Quest-Mac",HubOwnerBridge.Mac(config.Key,domain,"GET",path,config.OwnerEpoch,nonce,[]))};
        CaptureWireReply Get(string nonce,List<KeyValuePair<string,string>>? headers=null,IPAddress? peer=null)=>wire.Exchange("GET","/api/owner/status",headers??Headers(nonce),[],peer??IPAddress.Loopback);
        var nonce=CaptureOwnerTransport.NewNonce(now);Check(Get(nonce).Status==200&&Get(nonce).Status==409,"Nonce replay admitted");
        Check(Get(CaptureOwnerTransport.NewNonce(now),Headers(CaptureOwnerTransport.NewNonce(now),domain:"QMS-OWNER-REQUEST-1")).Status==401,"Wrong audience accepted");
        foreach(var hostile in new[]{"Origin","Authorization","Cookie"}){nonce=CaptureOwnerTransport.NewNonce(now);var h=Headers(nonce);h.Add(new(hostile,"forbidden"));Check(Get(nonce,h).Status==401,"Browser or bearer admitted");}
        nonce=CaptureOwnerTransport.NewNonce(now);var badHost=Headers(nonce);badHost[0]=new("Host","localhost:41234");Check(Get(nonce,badHost).Status==401&&Get(nonce,peer:IPAddress.Parse("127.0.0.2")).Status==401,"Host/peer drift admitted");
        nonce=CaptureOwnerTransport.NewNonce(now.AddMilliseconds(-30001));Check(Get(nonce).Status==401,"Stale nonce admitted");nonce=CaptureOwnerTransport.NewNonce(now.AddMilliseconds(2001));Check(Get(nonce).Status==401,"Future nonce admitted");
        for(var i=0;i<8300;i++){now=now.AddMilliseconds(10);Check(Get(CaptureOwnerTransport.NewNonce(now)).Status==200,"Routine reads hit finite poll cap");}
        now=now.AddMilliseconds(-1);Check(Get(CaptureOwnerTransport.NewNonce(now)).Status==503,"Regressed clock bypassed replay fence");now=now.AddMilliseconds(2);Check(Get(CaptureOwnerTransport.NewNonce(now)).Status==200,"Recovered clock stayed held");
        try{_ =new CaptureOwnerTransport(config,service,"127.0.0.1:41234");throw new Exception("Live epoch replay cache reset allowed");}catch(IOException){}
        var malformed="{\"schema\":\"questms.capture.action.v2\",\"schema\":\"foreign\"}"u8.ToArray();nonce=CaptureOwnerTransport.NewNonce(now);var postHeaders=new List<KeyValuePair<string,string>>{new("Host","127.0.0.1:41234"),new("Content-Type","application/json"),new("X-Quest-Owner-Epoch",config.OwnerEpoch),new("X-Quest-Nonce",nonce),new("X-Quest-Mac",HubOwnerBridge.Mac(config.Key,CaptureOwnerTransport.RequestDomain,"POST","/api/owner/capture-actions",config.OwnerEpoch,nonce,malformed))};Check(wire.Exchange("POST","/api/owner/capture-actions",postHeaders,malformed,IPAddress.Loopback).Status==400,"Duplicate JSON admitted");Check(!Directory.EnumerateDirectories(Path.Combine(root,"operations")).Any(),"Malformed request dispatched effect");
    }finally{Directory.Delete(root,true);}}
